BEGIN;
UPDATE sign_in_experiences SET
  branding = '{"logoUrl": "data:image/png;base64,", "darkLogoUrl": "data:image/png;base64,", "favicon": "data:image/png;base64,"}'::jsonb,
  color = '{"primaryColor": "#B74F30", "isDarkModeEnabled": false, "darkPrimaryColor": "#D9764F"}'::jsonb,
  language_info = '{"autoDetect": false, "fallbackLanguage": "zh-CN"}'::jsonb,
  custom_css = ':root, body, .logto_page-container {
  --color-bg-body: #f8f5ef;
  --color-bg-body-base: #f8f5ef;
  --color-bg-float: #fffdf9;
  --color-bg-float-base: #fffdf9;
  --color-bg-layer-1: #fffdf9;
  --color-type-primary: #282a25;
  --color-type-secondary: #6b6a60;
  --color-line-border: #e6e0d5;
  --color-line-divider: #e6e0d5;
}
body, .logto_page-container { background: #f8f5ef !important; }
.logto_main-content {
  background: #fffdf9 !important;
  border: 1px solid #e6e0d5;
  border-radius: 18px !important;
  box-shadow: 0 18px 50px rgba(82, 62, 40, .10) !important;
}
.logto_branding-header img { height: 60px !important; max-width: 200px; }
.logto_branding-header [class*="headline"] {
  font-family: Georgia, "Songti SC", "Noto Serif CJK SC", serif;
  font-weight: 600;
  letter-spacing: .02em;
}
input { background: #fffdf9 !important; }
'
WHERE tenant_id = 'default' AND id = 'default';
INSERT INTO custom_phrases (tenant_id, id, language_tag, translation)
VALUES ('default', 'easelzhcn', 'zh-CN', '{"description": {"sign_in_to_your_account": "登录 Easel", "create_your_account": "注册 Easel 账号"}}'::jsonb)
ON CONFLICT (tenant_id, language_tag) DO UPDATE SET translation = EXCLUDED.translation;
COMMIT;
